def title_of(html: str) -> str:
    """Text between the first <title> and the following </title> in html, or "" when either tag is missing."""
    post out.char_count() <= html.char_count()
    ex title_of("<html><title>Hi</title></html>") == "Hi"
    ex title_of("<p>no title</p>") == ""
    ex title_of("<title>unclosed") == ""
    opened = html.split("<title>")
    if opened.len() < 2:
        return ""
    closed = opened[1].split("</title>")
    if closed.len() < 2:
        return ""
    return closed[0].copy()
